// Unity is the rendering/input owner; JavaScript is the composition/storage owner.
export function mountUnityGame({getFrame,onEvent,locale=()=> 'zh'}){
 const stage=document.querySelector('#stage');if(!stage)return null;
 const words=(zh,en,ja)=>locale()==='zh'?zh:locale()==='ja'?ja:en;
 const host=document.createElement('div');host.className='unity-container';host.innerHTML='<canvas id="unity-canvas" tabindex="0" aria-label="互动插花画布"></canvas>';
 stage.append(host);const canvas=host.querySelector('canvas');canvas.width=canvas.height=800;canvas.addEventListener('contextmenu',e=>e.preventDefault());
 const bar=document.createElement('section');bar.className='game-session';bar.innerHTML=`<div class="game-session-title"><span class="game-live-dot"></span><span class="game-caption"></span></div><div class="game-session-modes"><button type="button" data-game-mode="free" aria-pressed="true"></button><button type="button" data-game-mode="practice" aria-pressed="false"></button><button type="button" id="game-photo"></button></div><div class="game-practice" hidden></div><p class="game-instruction"></p><div class="game-loading"><progress max="1" value="0"></progress><span></span><button type="button" id="game-retry" hidden></button></div>`;
 document.querySelector('.workspace-heading').after(bar);
 let instance=null,active=false,busy=false,queued=false,frameHandle=0,mode='free',revision=0,startPromise=null,disposed=false;
 const sentTextures=new Map(),milestones=new Set(),pendingEvents=[];
 function language(){bar.querySelector('.game-caption').textContent=words('一方花境，随手成景','A small world, shaped by you','一輪から、自分だけの景色を');bar.querySelector('[data-game-mode="free"]').textContent=words('自由花境','Free play','自由に生ける');bar.querySelector('[data-game-mode="practice"]').textContent=words('花道练习','Practice','生け花の練習');bar.querySelector('#game-photo').textContent=words('赏花模式 ↗','Photo mode ↗','鑑賞モード ↗');bar.querySelector('.game-instruction').textContent=words('拖动花枝 · 靠近瓶口吸附 · 拉圆点转向 · 双指旋转缩放','Drag to arrange · snap at the vase · pull the handle to turn · pinch to scale','ドラッグで配置・口元に吸着・ハンドルで回転・2本指で拡大縮小');bar.querySelector('#game-retry').textContent=words('重试加载','Retry','再試行');renderPractice();}
 function renderPractice(){const box=bar.querySelector('.game-practice');box.hidden=mode!=='practice';const steps=[['arrange',words('摆出枝的方向','Shape the stems','枝の方向を整える')],['light',words('为花景调光','Choose the light','光を選ぶ')],['save',words('收藏这一刻','Save your arrangement','この瞬間を保存')]];box.innerHTML=steps.map(([key,label],i)=>`<span class="${milestones.has(key)?'done':''}"><b>${milestones.has(key)?'✓':i+1}</b>${label}</span>`).join('');}
 const status=(text,value=null)=>{const box=bar.querySelector('.game-loading');box.hidden=false;box.querySelector('span').textContent=text;if(value!==null)box.querySelector('progress').value=value;};
 const visible=()=>!document.querySelector('#studio-view')?.hidden&&!document.querySelector('dialog[open]');
 function schedule(){if(disposed||!active||busy||!visible()){queued=true;return;}if(!frameHandle)frameHandle=requestAnimationFrame(()=>{frameHandle=0;sync()});}
 function sync(){if(!instance||!active||busy||!visible())return;language();try{const frame=getFrame();frame.revision=++revision;for(const node of frame.nodes){if(sentTextures.get(node.id)===node.key)node.texture='';else sentTextures.set(node.id,node.key);}for(const id of sentTextures.keys())if(!frame.nodes.some(n=>n.id===id))sentTextures.delete(id);instance.SendMessage('HanamaGame','ReceiveFrame',JSON.stringify(frame));queued=false;}catch(error){console.warn('Unity frame sync',error);}}
 window.hanamaUnityEvent=raw=>{let event;try{event=JSON.parse(raw)}catch{return;}if(event.type==='ready'){if(!instance){pendingEvents.push(event);return;}active=true;stage.classList.add('game-active');bar.querySelector('.game-loading').hidden=true;if(visible())canvas.focus({preventScroll:true});schedule();return;}if(!visible()){busy=false;return;}if(event.type==='begin')busy=true;if(event.type==='commit'||event.type==='cut'){busy=false;milestones.add('arrange');}if(event.type==='cancel')busy=false;onEvent(event);if(event.type!=='begin')schedule();};
 async function start(){if(startPromise)return startPromise;startPromise=(async()=>{language();status(words('正在布置花境…','Preparing your atelier…','花の空間を準備中…'),0);bar.querySelector('#game-retry').hidden=true;try{const configResponse=await fetch('/unity/build.json',{cache:'no-cache'});if(!configResponse.ok)throw new Error('Build unavailable');const config=await configResponse.json();await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=config.loader;script.onload=resolve;script.onerror=reject;document.head.append(script);});instance=await window.createUnityInstance(canvas,{...config,devicePixelRatio:Math.min(1.5,window.devicePixelRatio||1),matchWebGLToCanvasSize:true,companyName:'HANAMA',productName:'Light & Flowers',productVersion:'1.0',showBanner:(msg,type)=>{if(type==='error')console.warn('Unity',msg)}},progress=>status(words('正在布置花境…','Preparing your atelier…','花の空間を準備中…'),progress));for(const e of pendingEvents.splice(0))window.hanamaUnityEvent(JSON.stringify(e));}catch(error){console.warn('Unity startup',error);active=false;stage.classList.remove('game-active');status(words('花境载入失败。可继续使用画布，或点此重试。','The game could not load. Continue with the canvas or retry.','読み込めませんでした。キャンバスで続けるか再試行できます。'));bar.querySelector('#game-retry').hidden=false;startPromise=null;}})();return startPromise;}
 bar.querySelector('#game-retry').onclick=()=>start();
 bar.querySelectorAll('[data-game-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.gameMode;bar.querySelectorAll('[data-game-mode]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));renderPractice();});
 bar.querySelector('#game-photo').onclick=()=>{const on=document.body.classList.toggle('game-photo-mode');bar.querySelector('#game-photo').textContent=on?words('返回创作','Back to atelier','創作に戻る'):words('赏花模式 ↗','Photo mode ↗','鑑賞モード ↗');};
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('game-photo-mode');bar.querySelector('#game-photo').textContent=words('赏花模式 ↗','Photo mode ↗','鑑賞モード ↗');}});
 // Native pointer events must not bubble into the legacy gesture controller.
 for(const type of ['pointerdown','pointermove','pointerup','pointercancel','wheel','dblclick'])host.addEventListener(type,e=>{if(active)e.stopPropagation();},false);
 for(const button of document.querySelectorAll('[data-light],[data-scene]'))button.addEventListener('click',()=>{milestones.add('light');renderPractice();});
 document.addEventListener('hanama-saved',()=>{milestones.add('save');renderPractice();});
 const viewObserver=new MutationObserver(()=>{if(visible()){busy=false;schedule();}});viewObserver.observe(document.querySelector('#studio-view'),{attributes:true,attributeFilter:['hidden']});viewObserver.observe(document.querySelector('#modal'),{attributes:true,attributeFilter:['open']});
 new ResizeObserver(()=>{if(active){canvas.width=Math.round(host.clientWidth*Math.min(1.5,devicePixelRatio||1));canvas.height=Math.round(host.clientHeight*Math.min(1.5,devicePixelRatio||1));}}).observe(host);
 start();
 return {schedule,active:()=>active,busy:()=>busy,reset:()=>{sentTextures.clear();schedule();}};
}
